from __future__ import annotations

import asyncio
import re
from pathlib import Path

import httpx2
import pytest
from ds.util import graphql, http
from ds.util.logging import enable_call_logs, log_group, logger
from ds.util.logging.calls import CALL_LOGGER

PKGS = Path(__file__).resolve().parents[3] / "pkgs"


@pytest.fixture
def records():
    """The `log_call` records (their fields) emitted while the test runs"""
    found: list[dict] = []
    enable_call_logs()
    sink = logger.add(lambda m: found.append(m.record["extra"]), filter=lambda r: "kind" in r["extra"])
    yield found
    logger.remove(sink)
    logger.disable(CALL_LOGGER)


def _client(handler) -> httpx2.Client:
    return httpx2.Client(transport=httpx2.MockTransport(handler))


def _aclient(handler) -> httpx2.AsyncClient:
    return httpx2.AsyncClient(transport=httpx2.MockTransport(handler))


def test_a_request_is_logged_with_the_full_request_and_no_secrets(records):
    def handler(_):
        return httpx2.Response(200, json={"data": [1, 2]}, headers={"cf-ray": "abc-IAD"})

    with (
        _client(handler) as client,
        http.request(
            "POST",
            "https://example.com/search",
            source="example",
            name="search",
            client=client,
            params={"q": "sparg0"},
            headers={"Authorization": "Bearer s3cret", "apikey": "k3y", "User-Agent": "me"},
            json={"term": "sparg0"},
        ) as (resp, call),
    ):
        call["rows"] = len(resp.json()["data"])
    (r,) = records
    assert (r["kind"], r["source"], r["name"], r["method"]) == ("http", "example", "search", "POST")
    assert r["url"] == "https://example.com/search?q=sparg0"
    assert r["request_headers"]["authorization"] == "Bearer [filtered]"
    assert r["request_headers"]["apikey"] == "[filtered]"
    assert r["request_headers"]["user-agent"] == "me"
    assert r["request_body"] == {"term": "sparg0"}
    assert (r["status"], r["content_type"], r["cf_ray"], r["rows"], r["in_flight"]) == (
        200,
        "application/json",
        "abc-IAD",
        2,
        1,
    )
    assert "s3cret" not in repr(r)
    assert "k3y" not in repr(r)
    assert "error" not in r


@pytest.mark.parametrize(
    "body",
    [
        {"data": {"grant_type": "x", "client_secret": "s3cret", "code": "c0de"}},
        {"json": {"grant_type": "x", "client_secret": "s3cret", "code": "c0de"}},
    ],
)
def test_secret_body_fields_are_filtered(records, body):
    # eg an OAuth token request: its form carries the client secret and the sign-in code
    with (
        _client(lambda _: httpx2.Response(200)) as client,
        http.request("POST", "https://example.com/token", source="example", client=client, **body),
    ):
        pass
    (r,) = records
    assert r["request_body"] == {"grant_type": "x", "client_secret": "[filtered]", "code": "[filtered]"}
    assert "s3cret" not in repr(r)
    assert "c0de" not in repr(r)


def test_an_error_status_keeps_the_start_of_the_body_and_the_raised_error(records):
    def handler(_):
        return httpx2.Response(503, text="Site is paused " * 100, headers={"retry-after": "300"})

    with (
        pytest.raises(httpx2.HTTPStatusError),
        _client(handler) as client,
        http.request("GET", "https://example.com/p", source="example", client=client) as (resp, _),
    ):
        resp.raise_for_status()
    (r,) = records
    assert r["status"] == 503
    assert r["retry_after"] == "300"
    assert r["error_body"].startswith("Site is paused")
    assert len(r["error_body"]) == http.MAX_ERROR_CHARS
    assert "HTTPStatusError" in r["error"]


def test_redirects_are_recorded(records):
    def handler(request):
        if request.url.path == "/old":
            return httpx2.Response(301, headers={"location": "https://example.com/new"})
        return httpx2.Response(200, text="ok")

    with (
        _client(handler) as client,
        http.request("GET", "https://example.com/old", source="example", client=client, follow_redirects=True),
    ):
        pass
    (r,) = records
    assert (r["url"], r["final_url"], r["redirects"]) == ("https://example.com/old", "https://example.com/new", 1)


def test_an_async_redirect_is_recorded_too(records):
    # a request httpx2 builds to follow a redirect is never read into memory by the real
    # transport, so reading its body for the record used to raise RequestNotRead (eg a HEAD to
    # google.com, which redirects to www.google.com). MockTransport reads every request first,
    # hiding it: this transport answers without reading, as the real one does.
    class Unread(httpx2.AsyncBaseTransport):
        async def handle_async_request(self, request):
            if request.url.host == "google.com":
                return httpx2.Response(301, headers={"location": "https://www.google.com/"})
            return httpx2.Response(200, headers={"x-frame-options": "SAMEORIGIN"})

    async def run():
        async with (
            httpx2.AsyncClient(transport=Unread()) as client,
            http.arequest("HEAD", "https://google.com", source="browser", client=client, follow_redirects=True) as (
                resp,
                _,
            ),
        ):
            return resp.headers["x-frame-options"]

    assert asyncio.run(run()) == "SAMEORIGIN"
    (r,) = records
    assert (r["url"], r["final_url"], r["redirects"], r["request_body"]) == (
        "https://google.com",
        "https://www.google.com/",
        1,
        None,
    )


def test_a_request_that_never_got_an_answer_is_still_logged(records):
    def handler(request):
        raise httpx2.ConnectError("refused", request=request)

    with (
        pytest.raises(httpx2.ConnectError),
        _client(handler) as client,
        http.request("GET", "https://example.com/p", source="example", client=client, params={"a": "1"}),
    ):
        pass
    (r,) = records
    assert r["url"] == "https://example.com/p?a=1"
    assert "status" not in r
    assert "ConnectError" in r["error"]


def test_records_in_a_group_share_its_id(records):
    with _client(lambda _: httpx2.Response(200)) as client:
        with log_group("lookup") as group, log_group("inner") as inner:
            for _ in range(2):
                with http.request("GET", "https://example.com/p", source="example", client=client):
                    pass
        with http.request("GET", "https://example.com/p", source="example", client=client):
            pass
    assert inner == group
    assert re.fullmatch(r"lookup-[0-9a-f]{6}", group)
    assert [r.get("group") for r in records] == [group, group, None]


def test_curl_command_sends_the_same_request_with_secrets_as_variables():
    record = {
        "method": "POST",
        "url": "https://example.com/gql?x=1",
        "redirects": 1,
        "request_headers": {"authorization": "Bearer [filtered]", "content-type": "application/json", "host": "x"},
        "request_body": {"query": "query Q { a }", "variables": {"id": 1}},
    }
    curl = http.curl_command(record)
    assert curl.startswith("curl -sS -X POST 'https://example.com/gql?x=1'")
    assert '-H "authorization: Bearer $AUTHORIZATION"' in curl
    assert "-H 'content-type: application/json'" in curl
    assert "host" not in curl
    assert '--data-raw \'{"query":"query Q { a }","variables":{"id":1}}\'' in curl
    assert "-L" in curl
    assert http.curl_command({}) == ""


# --- graphql ----------------------------------------------------------------------------

_QUERY = "query PlayerSets($id: ID!) { player(id: $id) { sets { pageInfo { total } nodes { id } } } }"


def _gql(handler, **kwargs) -> graphql.GraphQLResult:
    async def run():
        async with _aclient(handler) as client:
            return await graphql.gql(
                "https://api.example.com/gql", _QUERY, {"id": 5}, source="example", client=client, **kwargs
            )

    return asyncio.run(run())


def test_graphql_logs_operation_rows_and_extensions(records):
    body = {
        "data": {"player": {"sets": {"pageInfo": {"total": 40, "page": 2}, "nodes": [{"id": 1}, {"id": 2}]}}},
        "extensions": {"queryComplexity": 66},
    }
    result = _gql(
        lambda _: httpx2.Response(200, json=body),
        headers={"Authorization": "Bearer t0ken"},
        extensions={"objects": "queryComplexity"},
        fields={"wait_ms": 3},
    )
    assert result.data == body["data"]
    assert result.errors == []
    (r,) = records
    assert (r["kind"], r["op"], r["variables"], r["query"]) == ("graphql", "PlayerSets", {"id": 5}, _QUERY)
    assert (r["rows"], r["page_info"], r["objects"], r["wait_ms"]) == (2, {"total": 40, "page": 2}, 66, 3)
    assert r["method"] == "POST"
    assert "request_body" not in r  # op, variables and query already are the body
    assert "t0ken" not in repr(r)


def test_graphql_errors_and_refusals_are_recorded():
    def refuse(_):
        return httpx2.Response(429, json={"success": False, "message": "Rate limit exceeded"})

    result = _gql(lambda _: httpx2.Response(200, json={"errors": [{"message": "no field x"}]}))
    assert result.errors == ["no field x"]
    assert result.data is None
    assert _gql(refuse).status == 429


def test_graphql_check_raises_inside_the_record(records):
    def check(result: graphql.GraphQLResult) -> None:
        if result.errors:
            raise ValueError(result.errors[0])

    with pytest.raises(ValueError, match="no field x"):
        _gql(lambda _: httpx2.Response(200, json={"errors": [{"message": "no field x"}]}), check=check)
    (r,) = records
    assert r["errors"] == ["no field x"]
    assert "no field x" in r["error"]


@pytest.mark.parametrize(
    ("document", "name"),
    [("query PlayerSets($id: ID!) { a }", "PlayerSets"), ("mutation Save { a }", "Save"), ("{ a }", "query")],
)
def test_operation_name(document, name):
    assert graphql.operation_name(document) == name


# --- the rule: outside calls go through ds.util.http ------------------------------------


def test_no_direct_httpx2_requests_in_pkgs():
    """Outside calls go through ds.util.http / graphql, so every one is logged the same way"""
    direct = re.compile(r"httpx2\.(get|post|put|patch|delete|head|request|stream)\(|\.(get|post)\(\s*[A-Z_]*URL")
    allowed = {PKGS / "ds" / "util" / "http.py"}
    offenders = [
        f"{path.relative_to(PKGS)}:{n}"
        for path in PKGS.rglob("*.py")
        if path not in allowed
        for n, line in enumerate(path.read_text().splitlines(), 1)
        if direct.search(line)
    ]
    assert offenders == [], "use ds.util.http.request / arequest (or ds.util.graphql.gql) instead"


def test_graphql_refusal_message_does_not_clash_with_the_log_message(records):
    _gql(lambda _: httpx2.Response(429, json={"success": False, "message": "Rate limit exceeded"}))
    (r,) = records
    assert r["api_message"] == "Rate limit exceeded"
    assert "message" not in r
